package org.apache.commons.math.stat.descriptive;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.MathIllegalStateException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.stat.descriptive.StorelessUnivariateStatistic;
import org.apache.commons.math.stat.descriptive.moment.GeometricMean;
import org.apache.commons.math.stat.descriptive.moment.Mean;
import org.apache.commons.math.stat.descriptive.moment.SecondMoment;
import org.apache.commons.math.stat.descriptive.moment.Variance;
import org.apache.commons.math.stat.descriptive.rank.Max;
import org.apache.commons.math.stat.descriptive.rank.Min;
import org.apache.commons.math.stat.descriptive.summary.Sum;
import org.apache.commons.math.stat.descriptive.summary.SumOfLogs;
import org.apache.commons.math.stat.descriptive.summary.SumOfSquares;
import org.apache.commons.math.stat.descriptive.univariate.GeometricMean;
import org.apache.commons.math.stat.descriptive.univariate.Mean;
import org.apache.commons.math.stat.descriptive.univariate.Variance;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.apache.commons.math.util.Precision;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.*;

public class SummaryStatistics_addValue_TriageGen1Test {

    private SummaryStatistics stats;

    @Before
    public void setUp() {
        stats = new SummaryStatistics();
    }

    @Test
    public void testAddValue_StandardFlow() {
        // Test adding a single value and verifying basic statistics
        stats.addValue(10.0);
        stats.addValue(20.0);

        assertEquals(2, stats.getN());
        assertEquals(30.0, stats.getSum(), 1e-10);
        assertEquals(500.0, stats.getSumsq(), 1e-10); // 10^2 + 20^2 = 100 + 400
        assertEquals(15.0, stats.getMean(), 1e-10);
        assertEquals(10.0, stats.getMin(), 1e-10);
        assertEquals(20.0, stats.getMax(), 1e-10);
    }

    @Test
    public void testAddValue_BranchCoverage_WithOverriddenImpls() {
        // To maximize branch coverage, we need to trigger the 'if' conditions
        // The conditions are:
        // if (!(meanImpl instanceof Mean))
        // if (!(varianceImpl instanceof Variance))
        // if (!(geoMeanImpl instanceof GeometricMean))

        // We will mock the implementations to NOT be instances of the specified classes
        StorelessUnivariateStatistic mockMean = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic mockVariance = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic mockGeoMean = mock(StorelessUnivariateStatistic.class);

        // Set mocks into stats
        stats.setMeanImpl(mockMean);
        stats.setVarianceImpl(mockVariance);
        stats.setGeoMeanImpl(mockGeoMean);

        double value = 5.0;
        stats.addValue(value);

        // Verify that because they are NOT instances of Mean/Variance/GeometricMean, 
        // increment() was called on them.
        verify(mockMean, times(1)).increment(value);
        verify(mockVariance, times(1)).increment(value);
        verify(mockGeoMean, times(1)).increment(value);

        // Verify n was incremented
        assertEquals(1, stats.getN());
    }

    @Test
    public void testAddValue_BranchCoverage_WithDefaultImpls() {
        // To test the 'else' logic (skipping increment), we provide implementations 
        // that ARE instances of the specified classes.

        // Note: In the real Apache Commons Math, the default implementations 
        // for meanImpl, varianceImpl, and geoMeanImpl are indeed 
        // instances of Mean, Variance, and GeometricMean respectively.

        // We use a real SummaryStatistics which uses default implementations.
        // Since we cannot easily inject a specific instance that IS a Mean 
        // without knowing the internal private field names or using reflection, 
        // we assume the default constructor provides them.

        // We'll use reflection to ensure we are testing the branch where they ARE instances.
        // However, the prompt asks for a professional test. 
        // Since we can't easily "mock" an instance of a class to be a specific type 
        // unless we actually use that class, we will use the actual classes.

        Mean realMean = new Mean();
        Variance realVariance = new Variance();
        GeometricMean realGeoMean = new GeometricMean();

        stats.setMeanImpl(realMean);
        stats.setVarianceImpl(realVariance);
        stats.setGeoMeanImpl(realGeoMean);

        // We need to track if increment was called. Since we can't easily verify 
        // calls on a real object without spying, we use spy.
        Mean spyMean = spy(realMean);
        Variance spyVariance = spy(realVariance);
        GeometricMean spyGeoMean = spy(realGeoMean);

        stats.setMeanImpl(spyMean);
        stats.setVarianceImpl(spyVariance);
        stats.setGeoMeanImpl(spyGeoMean);

        double value = 1.0;
        stats.addValue(value);

        // According to the code: 
        // if (!(meanImpl instanceof Mean)) { meanImpl.increment(value); }
        // Since spyMean IS an instance of Mean, increment should NOT be called by the SummaryStatistics logic.
        verify(spyMean, never()).increment(anyDouble());
        verify(spyVariance, never()).increment(anyDouble());
        verify(spyGeoMean, never()).increment(anyDouble());

        assertEquals(1, stats.getN());
    }

    @Test
    public void testAddValue_NegativeValues() {
        stats.addValue(-10.0);
        stats.addValue(-20.0);

        assertEquals(2, stats.getN());
        assertEquals(-30.0, stats.getSum(), 1e-10);
        assertEquals(-20.0, stats.getMax(), 1e-10);
        assertEquals(-20.0, stats.getMin(), 1e-10);
    }

    @Test
    public void testAddValue_Zero() {
        stats.addValue(0.0);
        assertEquals(1, stats.getN());
        assertEquals(0.0, stats.getSum(), 1e-10);
        assertEquals(0.0, stats.getMean(), 1e-10);
    }
}
